package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.PackageService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@Tag(name="Paquetes") @RestController @RequestMapping("/api/Paquetes") public class PackageController {private final PackageService s;public PackageController(PackageService s){this.s=s;}@Operation(summary="Listar paquetes activos")@GetMapping public Object list(){return s.list();}@Operation(summary="Crear paquete",security=@SecurityRequirement(name="bearerAuth"))@PostMapping@PreAuthorize("hasRole('ADMINISTRADOR')")public Object create(@Valid@RequestBody Requests.PackageTrip r){return Map.of("mensaje","Paquete creado correctamente.","paquete",s.create(r));}@Operation(summary="Actualizar paquete",security=@SecurityRequirement(name="bearerAuth"))@PutMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object update(@PathVariable int id,@Valid@RequestBody Requests.PackageTrip r){return Map.of("mensaje","Paquete actualizado correctamente.","paquete",s.update(id,r));}@Operation(summary="Desactivar paquete",security=@SecurityRequirement(name="bearerAuth"))@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disable(@PathVariable int id){s.disable(id);return Map.of("mensaje","Paquete desactivado correctamente.");}}
